        data(/repositorio/@nombre)
    }&lt;/nombre&gt;

    &lt;total_apuntes&gt;{
        count(/repositorio/carpeta/archivo)
    }&lt;/total_apuntes&gt;
&lt;/resumen_repositorio&gt;
